mapper.update:
    UPDATE sla_index_rebuild_lease
SET expires_at=#{expiresAt},updated_at=#{now},updated_by_type='SCHEDULER',
    lock_version=lock_version+1
WHERE tenant_id=#{tenantId} AND run_id=#{runId} AND fencing_epoch=#{fencingEpoch}
  AND state IN ('RUNNING','CATCHING_UP','SWAPPING')
  AND expires_at IS NOT NULL AND expires_at > #{now2}

    UPDATE sla_index_rebuild_lease SET state=#{state},run_id=NULL,expires_at=NULL,
    last_error_code=#{errorCode},lock_version=lock_version+1,updated_at=#{now},updated_by_type='SCHEDULER'
WHERE tenant_id=#{tenantId} AND run_id=#{runId} AND fencing_epoch=#{fencingEpoch}
